reference_solution:
def insert_spaces_at_indices(s,spaces):
    answer=[];next_space=0
    for index,char in enumerate(s):
        if next_space<len(spaces) and spaces[next_space]==index:answer.append(' ');next_space+=1
        answer.append(char)
    return ''.join(answer)

